// Helper to extract data from SEER StatFacts tabs
async function extractSeerData(tabId, cancerName) {
  return await browserjs(tabId, (cancerName) => {
    function getSection(headingText) {
      const el = Array.from(document.querySelectorAll('h2, h3, h4')).find(h => h.textContent.includes(headingText));
      if (!el) return null;
      let next = el.nextElementSibling;
      let text = "";
      while (next && !['H2', 'H3'].includes(next.tagName)) {
        text += next.innerText + "\n";
        next = next.nextElementSibling;
      }
      return text.trim();
    }
    return {
      cancer: cancerName,
      atAGlance: getSection("At a Glance"),
      survivalByStage: getSection("Survival by Stage"),
      whoGets: getSection("Who Gets This Cancer?"),
      whoDies: getSection("Who Dies From This Cancer?"),
    };
  }, cancerName);
}

